SQL_DOC.P_SQL:
SELECT PODT.PLANT , IVDT.INV_NO , IVDT.INV_SEQ , IVDT.STATUS , PODT.PO_NO , PODT.PO_SEQ , IVDT.INV_QTY , IVHD.INV_DATE FROM ICOMIVDT IVDT INNER JOIN ICOMPODT PODT ON (1 = 1 AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.PROCESS_TYPE = '0' ) INNER JOIN ICOMIVHD IVHD ON (1 = 1 AND IVHD.BUYER = IVDT.BUYER AND IVHD.INV_NO = IVDT.INV_NO AND IVHD.INV_TYPE = '0' ) WHERE 1 = 1 AND IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' UNION SELECT PODT.PLANT , IVDT.INV_NO , IVDT.INV_SEQ , IVDT.STATUS , PODT.PO_NO , PODT.PO_SEQ , IVDT.INV_QTY , IVDT.INV_DATE FROM WMSIVDT IVDT INNER JOIN ICOMPODT PODT ON (1 = 1 AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.PROCESS_TYPE = '2' ) WHERE 1 = 1 AND IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$'
BEGIN
IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVHD IVHD SET IVHD.SND_CHK = 'Y' , IVHD.SND_DATM = SYSDATE WHERE IVHD.BUYER = '$G_RS.BUYER$' AND IVHD.INV_NO = '$G_RS.INV_NO$' ; ELSE UPDATE WMSIVDT IVDT SET IVDT.SND_CHK = 'Y' , IVDT.SND_DATM = SYSDATE WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' ; END IF;
END;
BEGIN
IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVHD IVHD SET IVHD.SND_CHK = 'E' , IVHD.SND_DATM = SYSDATE WHERE IVHD.BUYER = '$G_RS.BUYER$' AND IVHD.INV_NO = '$G_RS.INV_NO$' ; ELSE UPDATE WMSIVDT IVDT SET IVDT.SND_CHK = 'E' , IVDT.SND_DATM = SYSDATE WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' ; END IF;
END;
